// Bare-metal protoacc round-trip test (no protobuf linked).
// Compiled once per smoke test with -DDATA_HEADER="<test>_data.h".
//
// The data header (generated by gen_data.cpp) provides:
//   - descriptor table arrays + patch_descriptors()
//   - ROOT_DESCRIPTOR        (the top-level descriptor table)
//   - serialized_input[] / SERIALIZED_INPUT_LEN
//   - TEST_NAME
//
// Flow: accelerator-parse the embedded serialized message, then
// accelerator-serialize the parsed object, and check the round-trip output
// equals the embedded input. This exercises both the deserialize (custom2)
// and serialize (custom3) accelerators with no runtime protobuf dependency.

#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <malloc.h>
#include <string>

#include "accellib.h"

#include DATA_HEADER

int main() {
    setvbuf(stdout, NULL, _IONBF, 0);   // unbuffered: progress visible even if we hang
    printf("protoacc baremetal round-trip test: %s\n", TEST_NAME);

    AccelSetup();
    printf("[1] AccelSetup done\n");
    volatile char ** ptrs = AccelSetupSerializer();
    printf("[2] AccelSetupSerializer done\n");
    patch_descriptors();
    printf("[3] patch_descriptors done\n");

    // region for the parsed top-level message object
    void * obj = memalign(4096, 4096);
    memset(obj, 0, 4096);

    std::string input((const char *)serialized_input, SERIALIZED_INPUT_LEN);

    // deserialize (custom2)
    AccelParseFromString_Helper((const void *)ROOT_DESCRIPTOR, obj, input);
    printf("[4] parse issued, blocking...\n");
    block_on_completion();
    printf("[5] parse complete\n");

    // serialize (custom3)
    AccelSerializeToString_Helper((const void *)ROOT_DESCRIPTOR, obj);
    printf("[6] serialize issued, blocking...\n");
    volatile char * outp = BlockOnSerializedValue(ptrs, 0);
    size_t outlen = GetSerializedLength(ptrs, 0);
    printf("[7] serialize complete\n");

    printf("input len %lu, round-trip output len %lu\n",
           (unsigned long)SERIALIZED_INPUT_LEN, (unsigned long)outlen);

    int fail = 0;
    if (outlen != SERIALIZED_INPUT_LEN) {
        fail = 1;
    } else {
        for (size_t i = 0; i < outlen; i++) {
            if ((unsigned char)outp[i] != serialized_input[i]) { fail = 1; break; }
        }
    }

    if (fail) {
        printf("FAILED %s round-trip test.\n", TEST_NAME);
        return 1;
    }
    printf("PASSED %s round-trip test.\n", TEST_NAME);
    return 0;
}
